const now = new Date();

// 3개월 전 시작 (00:00:00)
const start = new Date(now);
start.setMonth(now.getMonth() - 3);
start.setHours(0, 0, 0, 0);

// 오늘 끝 (23:59:59)
const end = new Date(now);
end.setHours(23, 59, 59, 999);

return [{
  json: {
    date_from: Math.floor(start.getTime() / 1000),
    date_to: Math.floor(end.getTime() / 1000),
    date_label: now.toISOString().slice(0, 10).replace(/-/g, '').slice(2)
  }
}];

const list = $input.first().json.data.list;
const accessToken = $('Call \'아임웹 인증 (서브)\'').item.json.access_token;

return list.map(order => ({
  json: {
    order_no: order.order_no,
    orderer_name: order.orderer?.name,
    total_price: order.payment?.total_price,
    order_time: order.order_time,
    access_token: accessToken
  }
}));

// 상태값 한국어 매핑
const STATUS_MAP = {
  'PAY_WAIT': '입금대기',
  'PAY_COMPLETE': '결제완료',
  'STANDBY': '배송준비중',
  'DELIVERING': '배송중',
  'COMPLETE': '배송완료',
  'CANCEL': '취소완료',
  'RETURN': '반품완료',
  'EXCHANGE': '교환완료',
  'PURCHASE_CONFIRMATION': '구매확정'
};

const __orders = $('주문코드 추출').all();
const __inputs = $input.all();
const rows = [];
for (let __i = 0; __i < __inputs.length; __i++) {
if (!__orders[__i]) continue; const meta = __orders[__i].json;
const __d = __inputs[__i].json && __inputs[__i].json.data; const detailList = Array.isArray(__d) ? __d : (__d ? [__d] : []); if (!__orders[__i]) continue;

// 날짜 형식 통일
const now = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }).replace('T', ' ');
const orderDate = new Date(meta.order_time * 1000).toLocaleString('sv-SE', { timeZone: 'Asia/Seoul' }).replace('T', ' ');

// rows / now are declared above the loop

for (const prodOrder of detailList) {
  const items = prodOrder.items ?? [];

  for (const item of items) {
    const prodName = item.prod_name ?? '';
    const options = item.options ?? [];

    // 옵션을 평탄화 (2중 배열 → 1차원)
    const flatOptions = [];
    for (const optGroup of options) {
      for (const opt of optGroup) {
        flatOptions.push(opt);
      }
    }

    if (flatOptions.length > 0) {
      // 옵션이 있는 경우: 옵션별로 행 생성
      for (const opt of flatOptions) {
        const optValue = opt.value_name_list?.[0] ?? '';
        const 유니크키 = `${meta.order_no}_${prodName}_${optValue}`;

        rows.push({
          json: {
            유니크키,
            적재일시: now,
            주문번호: meta.order_no,
            주문일시: orderDate,
            점주명: meta.orderer_name,
            상품명: prodName,
            옵션명: opt.option_name_list?.[0] ?? '',
            옵션값: optValue,
            수량: item.payment?.count ?? 0,
            단가: item.payment?.price ?? 0,
            배송비: item.payment?.deliv_price ?? 0,
            완료여부: STATUS_MAP[prodOrder.status] ?? prodOrder.status ?? '',
            주문상태: STATUS_MAP[prodOrder.status] ?? prodOrder.status ?? ''
          }
        });
      }
    } else {
      // 옵션이 없는 경우: 상품 자체로 1행 생성
      const 유니크키 = `${meta.order_no}_${prodName}_`;

      rows.push({
        json: {
          유니크키,
          적재일시: now,
          주문번호: meta.order_no,
          주문일시: orderDate,
          점주명: meta.orderer_name,
          상품명: prodName,
          옵션명: '',
          옵션값: '',
          수량: item.payment?.count ?? 0,
          단가: item.payment?.price ?? 0,
          배송비: item.payment?.deliv_price ?? 0,
          완료여부: STATUS_MAP[prodOrder.status] ?? prodOrder.status ?? '',
          주문상태: STATUS_MAP[prodOrder.status] ?? prodOrder.status ?? ''
        }
      });
    }
  }
}

}
return rows;
